def brackets_balanced(s: str) -> bool:
    stack = []
    in_string = False
    i = 0
    n = len(s)
    pairs = {')': '(', ']': '[', '}': '{'}

    while i < n:
        c = s[i]

        if in_string:
            if c == '\\':
                # Escaped character inside string
                if i + 1 >= n:
                    return False  # Unterminated string
                i += 2
                continue
            elif c == '"':
                in_string = False
            # Ignore all other characters inside string
            i += 1
        else:
            if c == '"':
                in_string = True
            elif c in '([{':
                stack.append(c)
            elif c in ')]}':
                if not stack or stack[-1] != pairs[c]:
                    return False
                stack.pop()
            # Ignore all other characters outside string
            i += 1

    return not in_string and not stack
